from collections import deque

def find_connected_components(grid, color):
    visited = set()
    regions = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color and (r, c) not in visited:
                region = []
                queue = deque([(r, c)])
                while queue:
                    cr, cc = queue.popleft()
                    if (cr, cc) not in visited:
                        visited.add((cr, cc))
                        region.append((cr, cc))
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == color:
                                queue.append((nr, nc))
                regions.append(region)
    return regions

# Find all regions for colors of interest
print("Regions by color:")
for color in [2, 7, 8]:
    regions = find_connected_components(grid, color)
    print(f"\n{color}-regions:")
    for r_idx, region in enumerate(regions):
